		t.Fatalf("wakeup = %+v, want at 15 with two events", resp.Wakeups[0])
	}
	if fired[0] != (ticklessFiredEvent{ID: "A", Event: 0, ScheduledAt: 10, Lateness: 5}) ||
		fired[1] != (ticklessFiredEvent{ID: "B", Event: 0, ScheduledAt: 12, Lateness: 3}) {
