3	import (
4		"container/heap"
5		"encoding/json"
6		"net/http"
7	)
8	
9	const (
10		ticklessSimulatePath = "/v1/timers/tickless/simulate"
11		// maxTicklessEvents bounds the total number of timer events generated
12		// within the horizon across all timers; maxTicklessWakeups bounds the
13		// actual number of wakeups the simulation performs.
14		maxTicklessEvents  = 100000
15		maxTicklessWakeups = 100000
16	)
17	
18	type ticklessTimerIn struct {
19		ID     string `json:"id"`
20		First  *int64 `json:"first"`
21		Period *int64 `json:"period"`
22	}
