39		At    int64                `json:"at"`
40		Fired []ticklessFiredEvent `json:"fired"`
41	}
42	
43	type ticklessEventResult struct {
44		Event       int   `json:"event"`
45		ScheduledAt int64 `json:"scheduledAt"`
46		FiredAt     int64 `json:"firedAt"`
47		Lateness    int64 `json:"lateness"`
48	}
49	
50	type ticklessTimerResult struct {
51		ID     string                `json:"id"`
52		Events []ticklessEventResult `json:"events"`
53	}
54	
55	type ticklessSimulateResponse struct {
56		WakeupCount int                   `json:"wakeupCount"`
57		Wakeups     []ticklessWakeup      `json:"wakeups"`
58		Results     []ticklessTimerResult `json:"results"`
59	}
60	
61	// simTimer carries the validated timer parameters.
62	type simTimer struct {
63		id     string
64		first  int64
65		period int64
66	}
67	
68	// pendingEvent is one not-yet-delivered timer event.
69	type pendingEvent struct {
70		scheduledAt int64
71		timerIdx    int
72		event       int
73	}
74	
75	// pendingHeap orders pending events by nominal time, then timer input order,
76	// then event number, matching the required delivery order.
77	type pendingHeap []pendingEvent
78	
79	func (h pendingHeap) Len() int { return len(h) }
80	func (h pendingHeap) Less(i, j int) bool {
81		if h[i].scheduledAt != h[j].scheduledAt {
82			return h[i].scheduledAt < h[j].scheduledAt
83		}
84		if h[i].timerIdx != h[j].timerIdx {
85			return h[i].timerIdx < h[j].timerIdx
86		}
87		return h[i].event < h[j].event
88	}
89	func (h pendingHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
90	func (h *pendingHeap) Push(x any)   { *h = append(*h, x.(pendingEvent)) }
91	func (h *pendingHeap) Pop() any {
92		old := *h
93		n := len(old)
94		x := old[n-1]
95		*h = old[:n-1]
96		return x
97	}
