99	func handleTicklessSimulate(w http.ResponseWriter, r *http.Request) {
100		if r.Method != http.MethodPost {
101			w.Header().Set("Allow", http.MethodPost)
102			writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
103			return
104		}
105		var req ticklessSimulateRequest
106		if !decodeStrictJSON(w, r, &req) {
107			return
108		}
109		timers, horizon, coalesceWindow, maxSleep, ok :=
110			validateTicklessSimulateRequest(&req)
111		if !ok {
112			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
113			return
114		}
115		resp := simulateTickless(timers, horizon, coalesceWindow, maxSleep)
116		if resp == nil {
117			// The expanded event set was within bounds, but the timer pattern
118			// would force more than maxTicklessWakeups actual wakeups.
119			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
120			return
121		}
122		w.Header().Set("Content-Type", "application/json; charset=utf-8")
123		w.WriteHeader(http.StatusOK)
124		_ = json.NewEncoder(w).Encode(resp)
125	}
126	
127	func validateTicklessSimulateRequest(req *ticklessSimulateRequest) (
128		timers []simTimer, horizon, coalesceWindow, maxSleep int64, ok bool,
129	) {
130		if req.Horizon == nil || *req.Horizon < 1 || *req.Horizon > maxHorizon {
131			return nil, 0, 0, 0, false
132		}
133		horizon = *req.Horizon
134		if req.CoalesceWindow == nil || *req.CoalesceWindow < 0 || *req.CoalesceWindow > maxHorizon {
135			return nil, 0, 0, 0, false
136		}
137		coalesceWindow = *req.CoalesceWindow
138		if req.MaxSleep == nil || *req.MaxSleep < 1 || *req.MaxSleep > maxHorizon {
139			return nil, 0, 0, 0, false
140		}
141		maxSleep = *req.MaxSleep
142		if req.Timers == nil || len(*req.Timers) == 0 || len(*req.Timers) > maxTasks {
143			return nil, 0, 0, 0, false
144		}
145		timers = make([]simTimer, 0, len(*req.Timers))
146		ids := make(map[string]struct{}, len(*req.Timers))
147		totalEvents := 0
148		for i := range *req.Timers {
149			in := (*req.Timers)[i]
150			if !validTaskID(in.ID) {
151				return nil, 0, 0, 0, false
152			}
153			if _, dup := ids[in.ID]; dup {
154				return nil, 0, 0, 0, false
155			}
156			ids[in.ID] = struct{}{}
157			if in.First == nil || *in.First < 0 || *in.First >= horizon {
158				return nil, 0, 0, 0, false
159			}
160			if in.Period == nil || *in.Period < 0 {
161				return nil, 0, 0, 0, false
162			}
163			// Events exist at first+k*period < horizon. period == 0 is a one-shot;
164			// otherwise the count is at least 1 because first < horizon, and the
165			// arithmetic stays well inside int64 since every operand is <= 1e12.
166			if *in.Period == 0 {
167				totalEvents++
168			} else {
169				totalEvents += int((horizon-*in.First-1)/(*in.Period) + 1)
170			}
171			if totalEvents > maxTicklessEvents {
172				return nil, 0, 0, 0, false
173			}
174			timers = append(timers, simTimer{
175				id:     in.ID,
176				first:  *in.First,
177				period: *in.Period,
178			})
179		}
180		return timers, horizon, coalesceWindow, maxSleep, true
181	}
182	
183	// ticklessEventCount returns the number of events a validated timer raises
184	// within [0,horizon): one for a one-shot, else first+k*period < horizon.
185	func ticklessEventCount(t simTimer, horizon int64) int {
186		if t.period == 0 {
187			return 1
188		}
189		return int((horizon-t.first-1)/t.period + 1)
190	}
191	
192	// simulateTickless runs the on-demand ("tickless") wakeup simulation, returning
193	// nil when it would perform more than maxTicklessWakeups wakeups.
194	//
195	// No fixed-period tick is ever generated: each wakeup time is derived solely
196	// from d, the earliest undelivered nominal deadline, as
197	// min(d+coalesceWindow, now+maxSleep, horizon). At a wakeup every event with a
198	// nominal time not later than the current time is delivered, ordered by nominal
199	// time, timer input order and event number. Periodic events are always derived
200	// from first+k*period, so delivery latency never drifts their nominal times.
201	func simulateTickless(timers []simTimer, horizon, coalesceWindow, maxSleep int64) *ticklessSimulateResponse {
202		n := len(timers)
203		counts := make([]int, n)
204		totalEvents := 0
205		for i := range timers {
206			counts[i] = ticklessEventCount(timers[i], horizon)
207			totalEvents += counts[i]
208		}
209	
210		// Expand every event up front; the request validator already bounded the
211		// total by maxTicklessEvents. The heap top is therefore always the
212		// earliest nominal deadline d among all undelivered events.
213		pending := make(pendingHeap, 0, totalEvents)
214		for i := range timers {
215			for k := 0; k < counts[i]; k++ {
216				at := timers[i].first
217				if timers[i].period > 0 {
218					at = timers[i].first + int64(k)*timers[i].period
219				}
220				pending = append(pending, pendingEvent{
221					scheduledAt: at,
222					timerIdx:    i,
223					event:       k,
224				})
225			}
226		}
227		heap.Init(&pending)
228	
229		results := make([]ticklessTimerResult, n)
230		for i := range timers {
231			results[i] = ticklessTimerResult{
232				ID:     timers[i].id,
233				Events: make([]ticklessEventResult, counts[i]),
234			}
235		}
236	
237		wakeups := make([]ticklessWakeup, 0)
238		delivered := 0
239		var now int64
240		for delivered < totalEvents {
241			d := pending[0].scheduledAt
242			wakeAt := d + coalesceWindow
243			if cap := now + maxSleep; cap < wakeAt {
244				wakeAt = cap
245			}
246			if horizon < wakeAt {
247				wakeAt = horizon
248			}
249			now = wakeAt
250	
251			// The wakeup about to be recorded is the (len+1)th; more than the
252			// allowed number of actual wakeups is a validation failure.
253			if len(wakeups) >= maxTicklessWakeups {
254				return nil
255			}
256	
257			// Deliver all events whose nominal time is not later than now; the
258			// heap yields them in (time, timer input order, event) order.
259			fired := make([]ticklessFiredEvent, 0)
260			for pending.Len() > 0 && pending[0].scheduledAt <= now {
261				ev := heap.Pop(&pending).(pendingEvent)
262				lateness := now - ev.scheduledAt
263				fired = append(fired, ticklessFiredEvent{
264					ID:          timers[ev.timerIdx].id,
265					Event:       ev.event,
266					ScheduledAt: ev.scheduledAt,
267					Lateness:    lateness,
268				})
269				// Per-timer results are indexed by event number directly: the
270				// nominal time first+k*period never depends on delivery latency.
271				results[ev.timerIdx].Events[ev.event] = ticklessEventResult{
272					Event:       ev.event,
273					ScheduledAt: ev.scheduledAt,
274					FiredAt:     now,
275					Lateness:    lateness,
276				}
277				delivered++
278			}
279			wakeups = append(wakeups, ticklessWakeup{At: now, Fired: fired})
280		}
281	
282		return &ticklessSimulateResponse{
283			WakeupCount: len(wakeups),
284			Wakeups:     wakeups,
285			Results:     results,
286		}
287	}
