41	
42	func TestTicklessOneShotExactWakeup(t *testing.T) {
43		resp := ticklessOK(t, `{"horizon":100,"coalesceWindow":0,"maxSleep":100,"timers":[
44			{"id":"A","first":10,"period":0}
