51			t.Fatalf("wakeup = %+v, want at 10 with one fired event", w)
52		}
53		if e := w.Fired[0]; e.ID != "A" || e.Event != 0 || e.ScheduledAt != 10 || e.Lateness != 0 {
54			t.Fatalf("fired = %+v", e)
55		}
56		if len(resp.Results) != 1 {
57			t.Fatalf("results = %+v, want one entry", resp.Results)
