61		}
62	}
63	
64	func TestTicklessCoalesceWindow(t *testing.T) {
65		// One-shots nominally due at 10 and 12; a window of 5 folds them into a
66		// single wakeup at 15 with lateness 5 and 3.
67		resp := ticklessOK(t, `{"horizon":100,"coalesceWindow":5,"maxSleep":100,"timers":[
68			{"id":"A","first":10,"period":0},
69			{"id":"B","first":12,"period":0}
70		]}`)
71		if resp.WakeupCount != 1 {
72			t.Fatalf("wakeups = %+v, want a single coalesced wakeup", resp.Wakeups)
73		}
74		fired := resp.Wakeups[0].Fired
75		if resp.Wakeups[0].At != 15 || len(fired) != 2 {
76			t.Fatalf("wakeup = %+v, want at 15 with two events", resp.Wakeups[0])
77		}
78		if fired[0] != (ticklessFiredEvent{ID: "A", Event: 0, ScheduledAt: 10, Lateness: 5}) ||
79			fired[1] != (ticklessFiredEvent{ID: "B", Event: 0, ScheduledAt: 12, Lateness: 3}) {
80			t.Fatalf("fired = %+v", fired)
81		}
82		a := resp.Results[0].Events[0]
83		b := resp.Results[1].Events[0]
84		if a != (ticklessEventResult{Event: 0, ScheduledAt: 10, FiredAt: 15, Lateness: 5}) {
85			t.Fatalf("A result = %+v", a)
86		}
87		if b != (ticklessEventResult{Event: 0, ScheduledAt: 12, FiredAt: 15, Lateness: 3}) {
88			t.Fatalf("B result = %+v", b)
89		}
90	}
91	
92	func TestTicklessMaxSleepEmptyWakeups(t *testing.T) {
93		// The only event is nominally due at 100; maxSleep 30 forces empty
94		// wakeups at 30, 60, 90 before the event fires at 100.
95		resp := ticklessOK(t, `{"horizon":200,"coalesceWindow":0,"maxSleep":30,"timers":[
96			{"id":"A","first":100,"period":0}
97		]}`)
98		if resp.WakeupCount != 4 || len(resp.Wakeups) != 4 {
99			t.Fatalf("wakeups = %+v, want four", resp.Wakeups)
100		}
101		wantAt := []int64{30, 60, 90, 100}
102		for i, at := range wantAt {
