153			{At: 8, Fired: []ticklessFiredEvent{{ID: "A", Event: 0, ScheduledAt: 0, Lateness: 8}}},
154			{At: 18, Fired: []ticklessFiredEvent{{ID: "A", Event: 1, ScheduledAt: 10, Lateness: 8}}},
155			{At: 25, Fired: []ticklessFiredEvent{{ID: "A", Event: 2, ScheduledAt: 20, Lateness: 5}}},
156		}
157		if len(resp.Wakeups) != len(wantWakeups) {
158			t.Fatalf("wakeups = %+v, want %+v", resp.Wakeups, wantWakeups)
159		}
160		for i := range wantWakeups {
161			if resp.Wakeups[i].At != wantWakeups[i].At ||
162				len(resp.Wakeups[i].Fired) != len(wantWakeups[i].Fired) ||
163				resp.Wakeups[i].Fired[0] != wantWakeups[i].Fired[0] {
164				t.Fatalf("wakeup %d = %+v, want %+v", i, resp.Wakeups[i], wantWakeups[i])
