171		// coalesce window of 10 then makes min(105, 120, 100) = horizon 100, so
172		// the event is delivered at the horizon with lateness 5.
173		resp := ticklessOK(t, `{"horizon":100,"coalesceWindow":10,"maxSleep":30,"timers":[
174			{"id":"A","first":95,"period":0}
