223	func TestTicklessEachEventDeliveredExactlyOnce(t *testing.T) {
224		resp := ticklessOK(t, `{"horizon":50,"coalesceWindow":7,"maxSleep":13,"timers":[
225			{"id":"A","first":0,"period":6},
226			{"id":"B","first":3,"period":11},
227			{"id":"C","first":49,"period":0}
228		]}`)
229		want := map[string]int{"A": 9, "B": 5, "C": 1} // A: 0..48, B: 3..47
230		seen := make(map[string]map[int]bool)
231		delivered := 0
232		for _, w := range resp.Wakeups {
233			for _, e := range w.Fired {
234				if seen[e.ID] == nil {
235					seen[e.ID] = make(map[int]bool)
236				}
237				if seen[e.ID][e.Event] {
238					t.Fatalf("event %s/%d delivered twice", e.ID, e.Event)
239				}
240				seen[e.ID][e.Event] = true
241				delivered++
242			}
243		}
244		total := 0
245		for id, n := range want {
246			total += n
247			if len(seen[id]) != n {
248				t.Fatalf("timer %s delivered %d unique events, want %d", id, len(seen[id]), n)
249			}
250		}
251		if delivered != total {
252			t.Fatalf("delivered %d events, want %d", delivered, total)
253		}
254		// Results mirror the same events once each in input/event order.
255		for i, tr := range resp.Results {
256			for k, e := range tr.Events {
257				if e.Event != k {
258					t.Fatalf("results %s[%d] event = %d", tr.ID, i, e.Event)
259				}
260				if !seen[tr.ID][k] {
261					t.Fatalf("result event %s/%d was never fired", tr.ID, k)
262				}
263			}
264		}
265	}
